"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["94760"],{92139(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.copia_da_oferta_de_curso.invalida","status":422,"titulo":"A oferta de curso n\xe3o tem curso, grau, unidade ofertante e turno v\xe1lidos"},"descricao":{"codigo":"uniplus.copia_da_oferta_de_curso.invalida","requisitos":["UNI-REQ-0506"],"oQueAconteceu":["Ao definir a distribui\xe7\xe3o de vagas, o processo seletivo copia por valor o que\\nnomeia cada oferta de curso para a pessoa candidata: o nome do curso, o grau, o\\nnome da unidade ofertante e os turnos. Essa c\xf3pia fica congelada com o processo,\\ne renomear o curso ou a unidade depois n\xe3o a altera. Para ser congelada, a c\xf3pia\\nprecisa ter curso, grau, unidade ofertante e ao menos um turno, sem caractere\\nnulo e dentro do tamanho permitido (curso at\xe9 200 caracteres, grau at\xe9 60,\\nunidade at\xe9 250 e turno at\xe9 30, depois da normaliza\xe7\xe3o do texto). Na defini\xe7\xe3o e\\nna simula\xe7\xe3o, a recusa aponta a oferta; na leitura da vers\xe3o congelada,\\nidentifica o campo que falhou.","Os dados v\xeam do cadastro de cursos e de ofertas de curso de Configura\xe7\xe3o, e\\naqui algum deles n\xe3o p\xf4de ser congelado: est\xe1 em branco, passa do tamanho ou\\ntraz caractere que o certame n\xe3o congela, como um n\xe3o-caractere do Unicode. Nada\\nfoi gravado. A **simula\xe7\xe3o** da distribui\xe7\xe3o de vagas devolve a mesma recusa,\\nsem gravar nada.","A recusa tamb\xe9m pode aparecer quando o sistema rel\xea a configura\xe7\xe3o congelada da\\nvers\xe3o publicada, nas demais opera\xe7\xf5es da lista do cabe\xe7alho (a lista completa \xe9\\na das opera\xe7\xf5es que propagam a falha da releitura). A consulta de conformidade\\ndo processo tamb\xe9m rel\xea a vers\xe3o, mas converte a falha em pend\xeancia do\\nchecklist, e por isso n\xe3o consta no cabe\xe7alho. Pelo caminho normal de grava\xe7\xe3o,\\na c\xf3pia congelada nunca traz uma oferta assim, porque a defini\xe7\xe3o da\\ndistribui\xe7\xe3o a recusa antes. Nessas leituras as recusas identificam os campos da\\noferta na vers\xe3o congelada, n\xe3o no pedido enviado."],"comoResolver":["Na defini\xe7\xe3o ou na simula\xe7\xe3o, corrija no cadastro de Configura\xe7\xe3o o curso ou a\\noferta de curso apontados (`PUT /api/configuracao/admin/cursos/{id}` ou\\n`PUT /api/configuracao/admin/ofertas-curso/{id}`), de modo que nome do curso,\\ngrau, nome da unidade ofertante e turnos fiquem preenchidos, no tamanho\\npermitido e sem caractere inv\xe1lido. Em seguida, defina a distribui\xe7\xe3o de vagas\\nde novo: a c\xf3pia \xe9 feita no momento da defini\xe7\xe3o, e a corre\xe7\xe3o do cadastro n\xe3o\\nchega sozinha a uma distribui\xe7\xe3o j\xe1 definida.","Se o erro apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer\\numa das listadas no cabe\xe7alho, exceto a defini\xe7\xe3o e a simula\xe7\xe3o da\\ndistribui\xe7\xe3o), o pedido enviado agora n\xe3o \xe9 a causa: o defeito est\xe1 na oferta de\\ncurso congelada na vers\xe3o publicada do processo. Corrigir o cadastro n\xe3o altera\\no que j\xe1 foi congelado. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo","Simula\xe7\xe3o da distribui\xe7\xe3o de vagas do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Defini\xe7\xe3o de etapas e do cronograma das fases de processo publicado, quando declaram atos","Apresenta\xe7\xe3o do formul\xe1rio do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, envio, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Copia da oferta de curso"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);